const ALL_SECTIONS: DictionaryEntry[][] = [
  A_WORDS,
  B_WORDS,
  C_WORDS,
  D_WORDS,
  E_WORDS,
  F_WORDS,
  G_WORDS,
  H_WORDS,
  I_WORDS,
  J_WORDS,
  K_WORDS,
  L_WORDS,
  M_WORDS,
  N_WORDS,
  O_WORDS,
  P_WORDS,
];

// ─── Initialization ─────────────────────────────────────────────────────

function initDictionary(): void {
  for (const section of ALL_SECTIONS) {
    for (const entry of section) {
      dictionaryMap.set(entry.word.toLowerCase(), entry);
    }
  }
}

// Initialize on module load
initDictionary();

// ─── Public API ─────────────────────────────────────────────────────────

/**
 * Look up a word in the local dictionary.
 * Case-insensitive. Returns undefined if not found.
 */
export function lookupWord(word: string): DictionaryEntry | undefined {
  return dictionaryMap.get(word.toLowerCase().trim());
}

/**
 * Check if a word exists in the local dictionary.
 */
export function hasWord(word: string): boolean {
  return dictionaryMap.has(word.toLowerCase().trim());
}

/**
 * Get the total number of entries in the local dictionary.
 */
export function getDictionarySize(): number {
  return dictionaryMap.size;
}

/**
 * Add a word to the local dictionary (in-memory + chrome.storage).
 * Useful for API results that should be cached for future lookups.
 */
export async function addToLocalDictionary(entry: DictionaryEntry): Promise<void> {
  const key = entry.word.toLowerCase().trim();
  dictionaryMap.set(key, entry);

  // Persist to chrome.storage for cross-session availability
  try {
    const { [LOCAL_DICT_KEY]: existing } = await chrome.storage.local.get(LOCAL_DICT_KEY);
    const stored: Record<string, DictionaryEntry> = existing || {};
    stored[key] = entry;
    await chrome.storage.local.set({ [LOCAL_DICT_KEY]: stored });
  } catch {
    // chrome.storage unavailable (e.g., in test environment) — continue silently
  }
}

/**
 * Load user-added words from chrome.storage into memory.
 * Should be called once at startup.
 */
export async function loadUserDictionary(): Promise<void> {
  try {
    const { [LOCAL_DICT_KEY]: stored } = await chrome.storage.local.get(LOCAL_DICT_KEY);
    if (stored) {
      for (const [key, entry] of Object.entries(stored as Record<string, DictionaryEntry>)) {
        dictionaryMap.set(key, entry);
      }
    }
  } catch {
    // chrome.storage unavailable
  }
}
